responses.text:
{
  "outcome": "revise",
  "issues": [
    {
      "kind": "contradiction",
      "severity": "critical",
      "description": "6행에서 중복 이름 신청 거부 시 참가 인원을 1 증가시키도록 규정하여, Scope R-2(신청/취소 실패 시 명단과 정원 계산 무변경), 기술 제약(인원과 실제 명단 일치), 그리고 3행·5행의 무변경 및 명단 길이 기반 계산 규칙과 정면으로 모순됩니다.",
      "suggestedDirection": "중복 신청 실패 시 참가 인원을 증가시키는 예외 규칙을 제거하고, 모든 신청/취소 실패 시 명단과 인원 수가 일절 변경되지 않도록 일관되게 명시하십시오.",
      "relatedRequirementId": "R-2"
    }
  ],
  "suggestions": [
    "실패 처리 규칙에서 임의의 시도 횟수 누적 로직을 배제하고 인원 계산을 항상 참가 명단 배열의 길이와 동기화하십시오."
  ],
  "scopeViolation": true,
  "userJudgmentRequired": false,
  "qualityAssessment": {
    "version": 1,
    "requirements": [
      {
        "requirementId": "R-1",
        "status": "satisfied",
        "evidenceLines": [3, 5],
        "rationale": "정원 2명 제한 및 중복 이름 거부 규칙이 이용 예시와 규칙 절에 명확히 정의되어 있습니다."
      },
      {
        "requirementId": "R-2",
        "status": "missing",
        "evidenceLines": [3, 6],
        "rationale": "3행에서는 실패 시 기존 명단/정원을 바꾸지 않는다고 하였으나, 6행에서 중복 이름 거부 시 참가 인원을 1 증가시키도록 규정하여 R-2 요구사항을 위반하고 있습니다."
      }
    ],
    "checks": [
      {
        "id": "decision_provenance",
        "status": "satisfied",
        "evidenceLines": [8],
        "rationale": "확정 규칙과 설계 제안의 출처가 정확히 구분되어 서술되어 있습니다."
      },
      {
        "id": "scope_compliance",
        "status": "missing",
        "evidenceLines": [6],
        "rationale": "Scope R-2 및 인원 일치 기술 제약을 위반하는 미승인 인원 증가 로직이 포함되어 있습니다."
      },
      {
        "id": "behavior_and_errors",
        "status": "missing",
        "evidenceLines": [3, 5, 6],
        "rationale": "3행·5행의 무변경 및 길이 기반 계산과 6행의 실패 시 인원 증가 규칙이 상호 충돌합니다."
      },
      {
        "id": "data_integrity",
        "status": "missing",
        "evidenceLines": [5, 6],
        "rationale": "인원은 실제 참가 명단과 일치해야 한다는 불변식이 실패 시 인원 임의 증가 규칙으로 인해 훼손됩니다."
      },
      {
        "id": "acceptance_criteria",
        "status": "satisfied",
        "evidenceLines": [3, 5],
        "rationale": "신청 순서, 정원 초과 오류, 취소 동작 등 구체적인 입력과 기대 결과가 명시되어 있습니다."
      },
      {
        "id": "revision_resolution",
        "status": "not_applicable",
        "evidenceLines": [],
        "rationale": "기존 settledDecisions 및 이전 수정 요청이 존재하지 않아 검토 대상이 없습니다."
      },
      {
        "id": "clarity",
        "status": "missing",
        "evidenceLines": [3, 5, 6],
        "rationale": "중복 신청 실패에 대한 상태 변경 규칙이 절마다 상충되어 구현 대상 동작이 모호합니다."
      }
    ]
  }
}
